package com.shopstream.demo;

import java.time.Duration;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.springframework.data.redis.core.BoundHashOperations;
import org.springframework.data.redis.core.HashOperations;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.ZSetOperations.TypedTuple;
import org.springframework.data.redis.connection.stream.RecordId;
import org.springframework.stereotype.Service;

@Service
public class ShopRedisOps {

    private final StringRedisTemplate redis;

    public ShopRedisOps(StringRedisTemplate redis) {
        this.redis = redis;
    }

    // String: flash-sale stock counter, and an idempotency key with TTL
    public long decrementStock(String sku) {
        Long left = redis.opsForValue().decrement("stock:" + sku);
        return left == null ? -1 : left;
    }

    public boolean firstTimeSeen(String idempotencyKey) {
        Boolean created = redis.opsForValue()
            .setIfAbsent("idem:" + idempotencyKey, "1", Duration.ofHours(24));
        return Boolean.TRUE.equals(created);
    }

    // Hash: cart:{userId}
    public void addToCart(String userId, String sku, int quantity) {
        redis.opsForHash().increment("cart:" + userId, sku, quantity);
        redis.expire("cart:" + userId, Duration.ofDays(7));
    }

    public Map<String, String> cart(String userId) {
        HashOperations<String, String, String> hash = redis.opsForHash();
        return hash.entries("cart:" + userId);
    }

    // Bound operations: fix the key once
    public void saveSession(String sid, String userId, String ip) {
        BoundHashOperations<String, String, String> session =
            redis.boundHashOps("session:" + sid);
        session.put("userId", userId);
        session.put("ip", ip);
        session.expire(Duration.ofMinutes(30));
    }

    // List: recent searches, newest first, capped at 10
    public void recordSearch(String userId, String term) {
        String key = "recent:search:" + userId;
        redis.opsForList().leftPush(key, term);
        redis.opsForList().trim(key, 0, 9);
    }

    public List<String> recentSearches(String userId) {
        return redis.opsForList().range("recent:search:" + userId, 0, 9);
    }

    // Set: unique tags
    public Set<String> tags(String sku) {
        redis.opsForSet().add("tags:" + sku, "kitchen", "steel");
        return redis.opsForSet().members("tags:" + sku);
    }

    // Sorted set: daily bestsellers leaderboard
    public void recordSale(String sku, int units) {
        redis.opsForZSet().incrementScore("lb:bestsellers:daily", sku, units);
    }

    public Set<TypedTuple<String>> topSellers() {
        return redis.opsForZSet().reverseRangeWithScores("lb:bestsellers:daily", 0, 9);
    }

    // Stream: order events
    public RecordId publishOrder(String orderId, String userId) {
        return redis.opsForStream()
            .add("stream:orders", Map.of("orderId", orderId, "userId", userId));
    }
}

