package com.shopstream.notification;

import java.time.Duration;
import java.util.List;
import org.springframework.data.domain.Range;
import org.springframework.data.redis.connection.stream.MapRecord;
import org.springframework.data.redis.connection.stream.PendingMessage;
import org.springframework.data.redis.connection.stream.PendingMessages;
import org.springframework.data.redis.connection.stream.RecordId;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
public class PendingReclaimer {

    private static final String STREAM = "stream:orders";
    private static final String GROUP = "notifier";
    private static final String DLQ = "stream:orders:dlq";
    private static final int MAX_DELIVERIES = 5;
    private final StringRedisTemplate redis;
    private final EmailSender emailSender;
    private final String consumerName = "reclaimer";

    public PendingReclaimer(StringRedisTemplate redis, EmailSender emailSender) {
        this.redis = redis;
        this.emailSender = emailSender;
    }

    @Scheduled(fixedDelay = 30_000)
    public void reclaim() {
        PendingMessages pending = redis.opsForStream()
            .pending(STREAM, GROUP, Range.unbounded(), 100);
        for (PendingMessage p : pending) {
            if (p.getElapsedTimeSinceLastDelivery().compareTo(Duration.ofMinutes(1)) < 0) {
                continue; // still being worked on by its consumer
            }
            RecordId id = p.getId();
            List<MapRecord<String, Object, Object>> claimed = redis.opsForStream()
                .claim(STREAM, GROUP, consumerName, Duration.ofMinutes(1), id);
            for (MapRecord<String, Object, Object> record : claimed) {
                handle(record, p.getTotalDeliveryCount());
            }
        }
    }

    private void handle(MapRecord<String, Object, Object> record, long deliveries) {
        if (deliveries >= MAX_DELIVERIES) {
            redis.opsForStream().add(DLQ, java.util.Map.of(
                "origId", record.getId().getValue(),
                "orderId", String.valueOf(record.getValue().get("orderId"))));
            redis.opsForStream().acknowledge(STREAM, GROUP, record.getId());
            return;
        }
        try {
            emailSender.sendOrderConfirmation(String.valueOf(record.getValue().get("orderId")));
            redis.opsForStream().acknowledge(STREAM, GROUP, record.getId());
        } catch (RuntimeException e) {
            // leave it pending; the next run tries again and the delivery count grows
        }
    }
}

package com.shopstream.gateway;

import java.time.Duration;
import org.springframework.data.redis.core.ReactiveStringRedisTemplate;
import org.springframework.stereotype.Component;
import reactor.core.publisher.Mono;

@Component
public class VisitCounter {

    private final ReactiveStringRedisTemplate redis;

    public VisitCounter(ReactiveStringRedisTemplate redis) {
        this.redis = redis;
    }
    /** Counts a visit and returns the new total for the page. */
    public Mono<Long> hit(String page) {
        String key = "visits:" + page;
        return redis.opsForValue().increment(key)
            .flatMap(total -> total == 1
                ? redis.expire(key, Duration.ofDays(1)).thenReturn(total)
                : Mono.just(total));
    }

    public Mono<String> lastSeenIp(String sessionId) {
        return redis.opsForValue().get("session:" + sessionId + ":ip");
    }
}

