package com.shopstream.catalog;

import java.time.Duration;
import java.util.function.Function;
import org.springframework.data.redis.core.ReactiveRedisTemplate;
import org.springframework.stereotype.Component;
import reactor.core.publisher.Mono;
@Component
public class ReactiveProductCache {

    private final ReactiveRedisTemplate<String, ProductView> template;

    public ReactiveProductCache(ReactiveRedisTemplate<String, ProductView> template) {
        this.template = template;
    }

    /** Cache-aside: Redis first, loader on a miss, then store with a TTL. */
    public Mono<ProductView> get(long id, Function<Long, Mono<ProductView>> loader) {
        String key = "product:" + id;
        return template.opsForValue().get(key)
            .switchIfEmpty(Mono.defer(() -> loader.apply(id)
                .flatMap(p -> template.opsForValue()
                    .set(key, p, Duration.ofMinutes(10))
                    .thenReturn(p))));
    }
}

package com.shopstream.inventory;

import java.util.List;
import org.springframework.dao.DataAccessException;
import org.springframework.data.redis.core.RedisOperations;
import org.springframework.data.redis.core.SessionCallback;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Service;

@Service
public class StockReservation {

    private final StringRedisTemplate redis;

    public StockReservation(StringRedisTemplate redis) {
        this.redis = redis;
    }

    /** Reserves one unit with optimistic locking; returns false if someone else changed it. */
    public boolean reserveOne(String sku, String reservationId) {
        String stockKey = "stock:" + sku;
        List<Object> result = redis.execute(new SessionCallback<List<Object>>() {
            @Override
            @SuppressWarnings({"unchecked", "rawtypes"})
            public List<Object> execute(RedisOperations operations) throws DataAccessException {
                operations.watch(stockKey);
                Object current = operations.opsForValue().get(stockKey);
                if (current == null || Long.parseLong(current.toString()) <= 0) {
                    operations.unwatch();
                    return List.of();
                }
                operations.multi();
                operations.opsForValue().decrement(stockKey);
                operations.opsForSet().add("reserved:" + sku, reservationId);
                return operations.exec();
            }
        });
        return result != null && !result.isEmpty();
    }
}

package com.shopstream.inventory;

import java.util.List;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.io.ClassPathResource;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import org.springframework.data.redis.core.script.RedisScript;
import org.springframework.scripting.support.ResourceScriptSource;
import org.springframework.stereotype.Service;

@Configuration
class ScriptConfig {

    @Bean
    RedisScript<Long> reserveStockScript() {
        DefaultRedisScript<Long> script = new DefaultRedisScript<>();
        ClassPathResource file = new ClassPathResource("scripts/reserve_stock.lua");
        script.setScriptSource(new ResourceScriptSource(file));
        script.setResultType(Long.class);
        return script;
    }
}

@Service
public class InventoryService {

    private final StringRedisTemplate redis;
    private final RedisScript<Long> reserveStockScript;

    public InventoryService(StringRedisTemplate redis, RedisScript<Long> reserveStockScript) {
        this.redis = redis;
        this.reserveStockScript = reserveStockScript;
    }

    public boolean reserve(String sku, int quantity) {
        Long result = redis.execute(
            reserveStockScript, List.of("stock:" + sku), String.valueOf(quantity));
        if (result == null || result < 0) {
            throw new IllegalStateException("unknown SKU " + sku);
        }
        return result == 1L;
    }
}

package com.shopstream.cart;

import java.util.List;
import org.springframework.data.redis.core.RedisCallback;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;

@Component
public class CartCountLoader {

    private final StringRedisTemplate redis;

    public CartCountLoader(StringRedisTemplate redis) {
        this.redis = redis;
    }

    /** Returns the number of distinct items in each user's cart, one round trip. */
    public List<Object> itemCounts(List<Long> userIds) {
        return redis.executePipelined(
            (RedisCallback<Object>) connection -> {
                for (Long userId : userIds) {
                    connection.hashCommands().hLen(("cart:" + userId).getBytes());
                }
                return null;
            });
    }
}

